<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { accountApi as api } from '../accountApi'
const config=ref<any>(null),orders=ref<any[]>([]),otp=ref(''),error=ref(''),message=ref(''),busy=ref(false),offset=ref(0),total=ref(0)
const networks=[{id:'usdt_ton',name:'USDT · TON (Jetton)',hint:'UQ… / EQ…',description:'Официальный master USDT зафиксирован сервером. Укажите адрес владельца, не Jetton-кошелёк.'},{id:'gram',name:'GRAM · TON (Jetton)',hint:'UQ… / EQ…',description:'Укажите выбранный GRAM Jetton master. Символ GRAM сам по себе не идентифицирует токен. Decimals: 9.'},{id:'trc20',name:'USDT · TRON (TRC-20)',hint:'T…',description:'Только USDT контракта TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t. Точные суммы счетов уникальны и не переиспользуются.'},{id:'bep20',name:'Binance-Peg USDT · BNB Smart Chain',hint:'0x…',description:'Сеть 56. Контракт 0x55d398326f99059ff775485246999027b3197955. Не Tether-native USDT; подтверждение после 20 блоков.'}]
const poolProviders=['ton','usdt_ton','gram','trc20','bep20']
const poolText=ref<Record<string,string>>({})
const prices=computed(()=>{const all=config.value?.prices||[];const canonical=all.filter((p:any)=>['pro_1m','pro_6m','pro_12m'].includes(p.code));return canonical.length?canonical:all})
function title(p:any){return p.days===30?'1 месяц · 30 дней':p.days===180?'6 месяцев · 180 дней':p.days===365?'12 месяцев · 365 дней':p.title}
async function load(){const [c,o]=await Promise.all([api('/admin/billing/settings'),api('/admin/billing/orders?offset='+offset.value)]);for(const n of networks){c.networks[n.id]||={receiver:'',master:''}}for(const id of poolProviders){poolText.value[id]=(c.networks[id]?.address_pool||[]).join('\n')}config.value=c;orders.value=o.items;total.value=o.total}
async function save(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{for(const id of poolProviders){config.value.networks[id]||={receiver:'',master:''};config.value.networks[id].address_pool=(poolText.value[id]||'').split(/\s+/).filter(Boolean)}await api('/admin/billing/settings','PUT',{ton_receiver:config.value.ton_receiver,networks:config.value.networks,prices:prices.value.map((p:any)=>({plan_id:p.plan_id,usd:p.usd,ton:p.ton,stars:Number(p.stars),usdt_ton:p.usdt_ton,gram:p.gram,trc20:p.trc20,bep20:p.bep20}))},otp.value);message.value='Реквизиты и цены сохранены. Созданные ранее счета не изменены.';await load()}catch(e:any){error.value=e.message}finally{busy.value=false;otp.value=''}}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section class="billing-settings"><header><p class="eyebrow">KINOSOTA · NON-CUSTODIAL CHECKOUT</p><h2>Подписки и приём платежей</h2><p>Три периода PRO, пять крипто-маршрутов и Telegram Stars. Сервер сверяет сеть, контракт, получателя, точную сумму и подтверждение транзакции. Приватные ключи не нужны.</p></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><form v-if="config" @submit.prevent="save"><div class="config-note"><strong>Безопасная активация</strong><p>Пустой адрес или нулевая цена отключают способ оплаты. Демонстрационные адреса не подставляются в реальные счета. Сохранение требует текущего 2FA-кода.</p></div><h3>Address Pool · отдельный адрес на счёт</h3><p>По одному вашему депозитному адресу на строку. Адрес закрепляется навсегда, даже после истечения счёта. Пустой пул сохраняет прежний способ сверки. Приватные ключи не вводите.</p><label v-for="id in poolProviders" :key="id">{{id}}<textarea v-model="poolText[id]" rows="3" style="display:block;width:100%;box-sizing:border-box;background:#101725;color:white;border:1px solid #646078;border-radius:10px;padding:12px"/></label><h3>Цены · 1 / 6 / 12 месяцев</h3><div class="tariff-grid"><article v-for="p in prices" :key="p.plan_id" class="tariff"><h4>PRO · {{title(p)}}</h4><small>{{p.is_active?'Продажи включены':'Продажи отключены'}}</small><div class="field-grid"><label>USD · витрина<input v-model="p.usd" type="number" min="0" max="1000000" step="0.01" required/></label><label>★ Stars<input v-model="p.stars" type="number" min="0" max="1000000" step="1" required/></label><label>TON<input v-model="p.ton" type="number" min="0" max="1000000" step="0.000000001" required/></label><label>GRAM · Jetton<input v-model="p.gram" type="number" min="0" max="1000000" step="0.000000001" required/></label><label>USDT · TON<input v-model="p.usdt_ton" type="number" min="0" max="1000000" step="0.000001" required/></label><label>USDT · TRC-20<input v-model="p.trc20" type="number" min="0" max="1000000" step="0.000001" required/></label><label>USDT · BEP-20<input v-model="p.bep20" type="number" min="0" max="1000000" step="0.000001" required/></label></div></article></div><p>TON и GRAM: фиксированная цена в монетах, без скрытого обменного курса. USDT TRC-20 / BEP-20: счёт добавляет от 0.000001 до 0.009999 USDT для однозначного определения заказа; эта точная сумма показана до отправки.</p><h3>Реквизиты по сетям</h3><div class="address-grid"><article class="address-card"><h4>TON · Toncoin</h4><label>Адрес владельца<input v-model="config.ton_receiver" maxlength="80" placeholder="UQ… / EQ…"/></label><p>Сырой формат 0:… нормализуется в mainnet Base64url. Пустые и burn-адреса не используются в счёте.</p></article><article v-for="n in networks" :key="n.id" class="address-card"><h4>{{n.name}}</h4><label>Адрес получателя<input v-model="config.networks[n.id].receiver" maxlength="80" :placeholder="n.hint"/></label><label v-if="n.id==='gram'">GRAM Jetton master<input v-model="config.networks.gram.master" maxlength="80" placeholder="EQ… / UQ…"/></label><p>{{n.description}}</p></article></div><p>Telegram Stars: <strong>{{config.stars_configured?'бот настроен на VPS 1':'бот не настроен'}}</strong>. Секреты бота не передаются на Витрину.</p><p v-if="config.ton_scanner">Проверка сетей: {{config.ton_scanner.error||'нет ошибок последнего цикла'}} · {{config.ton_scanner.last_success_at||'успешных циклов ещё нет'}}</p><div class="save-row"><label>Текущий код 2FA / резервный код<input v-model="otp" autocomplete="one-time-code" maxlength="64" required/></label><button :disabled="busy">{{busy?'Сохраняем…':'Сохранить реквизиты и цены'}}</button><router-link to="/account-security">Безопасность администратора →</router-link></div></form><h3>Все входящие платежи · {{total}}</h3><div class="table-scroll"><table><thead><tr><th>Дата / Пользователь</th><th>Тариф</th><th>Сумма / Сеть</th><th>Статус</th><th>Подтверждение</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{new Date(o.created_at).toLocaleString()}}<small>{{o.user_id}}</small></td><td>{{o.plan_title}} · {{o.duration_days}} дн.</td><td>{{o.amount_display}} {{o.payment?.symbol||o.provider}}<small>{{o.payment?.network}}</small></td><td>{{o.status}}</td><td class="mono">{{o.provider_ref||'—'}}</td></tr><tr v-if="!orders.length"><td colspan="5">После первой подтверждённой оплаты здесь появятся её реквизиты и статус.</td></tr></tbody></table></div><div class="actions" v-if="total>50"><button :disabled="!offset" @click="offset-=50;load()">Назад</button><button :disabled="offset+50>=total" @click="offset+=50;load()">Далее</button></div></section></template>
<style scoped>.billing-settings{padding:28px;background:linear-gradient(145deg,#232039,#151d2d);border:1px solid #414055;border-radius:20px;color:#eceaf7;min-width:0;font-size:16px;line-height:1.5}.eyebrow{color:#bda8fa!important;font-size:14px;letter-spacing:.1em}.billing-settings h2{font-size:27px;letter-spacing:-.03em;margin:0 0 16px}.billing-settings h3{font-size:20px;margin:32px 0 16px}.billing-settings h4{margin:0 0 8px;font-size:17px}.billing-settings p{color:#b6b8cd;font-size:14px;line-height:1.7}.billing-settings small{font-size:14px;color:#b8adcf}.billing-settings label{display:block;font-size:14px;color:#dcd6eb;margin:14px 0}.billing-settings input{box-sizing:border-box;width:100%;padding:12px;margin-top:8px;background:#101725;border:1px solid #646078;border-radius:10px;color:#fff;font:inherit;min-height:46px}.billing-settings input:focus{outline:2px solid #bc9cf7;outline-offset:3px}.tariff-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.tariff,.address-card{border:1px solid #56506b;background:#141b2a80;border-radius:16px;padding:20px;min-width:0}.tariff:nth-child(2){border-color:#a486de;background:linear-gradient(140deg,#412d5966,#192436)}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}.address-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.config-note{padding:18px 20px;background:#3a2f4d;border:1px solid #77658f;border-radius:12px}.config-note p{margin-bottom:0}.save-row{display:flex;align-items:end;gap:18px;flex-wrap:wrap;border-top:1px solid #4f475f;margin-top:24px;padding-top:14px}.save-row label{flex:1;min-width:200px}.billing-settings button{padding:13px 17px;border:0;border-radius:10px;background:linear-gradient(115deg,#bd9ef9,#9ab8fa);color:#171327;font:inherit;font-size:14px;font-weight:650;cursor:pointer;min-height:46px;margin-bottom:14px}.billing-settings a{display:inline-block;margin:14px;color:#d4c2ff;font-size:14px}.billing-settings button:disabled{opacity:.5}.table-scroll{overflow:auto}.billing-settings table{width:100%;border-collapse:collapse;font-size:14px;text-align:left}.billing-settings td,.billing-settings th{border-bottom:1px solid #464154;padding:14px 12px}.billing-settings td small{display:block;margin-top:6px;overflow-wrap:anywhere}.mono{font-family:monospace;max-width:200px;overflow-wrap:anywhere}.actions{display:flex;gap:10px;margin-top:14px}.notice{padding:14px;border-radius:10px;background:#173e32;color:#b0f1d3!important}.notice.error{background:#472737;color:#ffd3e3!important}@media(max-width:1100px){.tariff-grid{grid-template-columns:1fr}.field-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:650px){.field-grid,.address-grid{grid-template-columns:1fr}.billing-settings{padding:20px}.save-row{display:block}}</style>
